(6, 1, 3, 9, 'Rawat Jalan', 2, 1, DATE_ADD(DATE_SUB(CURDATE(), INTERVAL 88 DAY), INTERVAL 846 MINUTE), 'Pengkajian Awal', 8, DATE_ADD(DATE_SUB(CURDATE(), INTERVAL 88 DAY), INTERVAL 855 MINUTE), 'PENGKAJIAN-3', '131/87', 91, 17, 36.7, 97, 60.0, 173, NULL, 0, 'Sering haus dan buang air kecil malam hari', 'Riwayat penyakit: Diabetes melitus tipe 2. Alergi obat/makanan: Debu & tungau.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Final', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(7, 1, 3, 9, 'Rawat Jalan', 2, 1, DATE_ADD(DATE_SUB(CURDATE(), INTERVAL 88 DAY), INTERVAL 846 MINUTE), 'SOAP Dokter', 1, DATE_ADD(DATE_SUB(CURDATE(), INTERVAL 88 DAY), INTERVAL 880 MINUTE), 'SOAP-3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Sering haus, sering BAK terutama malam hari, kesemutan di kedua kaki. Riwayat DM 3 tahun, obat tidak teratur.', 'TD 131/87, N 91. IMT 27. Kaki: sensasi monofilamen menurun di plantar pedis bilateral, ulkus (-), pulsasi a. dorsalis pedis teraba.', 'Diabetes melitus tipe 2 belum terkontrol dengan neuropati perifer', 'E11.9', 'Metformin 3x500 mg sesudah makan, Glimepiride 1x2 mg pagi. Edukasi diet 3J & perawatan kaki. Cek HbA1c. Kontrol 1 bulan.', 'Kontrol', 'Final', DATE_ADD(DATE_SUB(CURDATE(), INTERVAL 88 DAY), INTERVAL 882 MINUTE), 'Lengkap', NULL, 23, 'SAT-2026-000003', NULL, NULL, NULL, NULL, 0, NULL, NULL),
