-- =====================================================================
--  SIMRS RS USHI (Rumah Sakit Untuk Semua Hari Ini) -- Kelompok 10
--  Skema database + data contoh
--  Database : MySQL 8 / MariaDB 10.4+ (XAMPP)
--
--  CARA IMPORT (XAMPP):
--    1. Nyalakan Apache dan MySQL di XAMPP Control Panel.
--    2. Buka http://localhost/phpmyadmin -> klik tab "Import"
--       -> Choose File -> pilih file ini -> klik "Import" (atau "Go").
--       Database db_simrs_ushi dibuat otomatis.
--
--  File ini AMAN diulang: semua tabel dihapus lalu dibuat ulang
--  (data yang Anda input sendiri ikut terhapus).
--  Seluruh akun demo memakai password: password
--
--  PRINSIP: SATU TABEL INDUK UNTUK SATU KATEGORI, dibedakan kolom jenis.
--  ---------------------------------------------------------------------
--   KATEGORI                TABEL                    DIBEDAKAN OLEH
--   1  Konfigurasi RS       konfigurasi_rs           jenis (Pusat / Cabang)
--   2  Hak akses (RBAC)     role, modul, hak_akses
--   3  Kepegawaian          pegawai                  jenis_tenaga (Dokter,
--                                                    Perawat, Bidan, Apoteker,
--                                                    Analis Lab, Radiografer,
--                                                    Administrasi) -- sekaligus
--                                                    akun login & role
--                           jadwal_pegawai           jenis (Praktik / Shift)
--   4  Unit & ruangan       unit_layanan             jenis (Poliklinik, IGD,
--                                                    Rawat Inap)
--                           bed                      (bed milik unit Rawat Inap)
--   5  Layanan & tarif      layanan                  kategori (Administrasi,
--                                                    Tindakan, Laboratorium,
--                                                    Radiologi, Paket Lab)
--   6  Referensi            penjamin, icd10
--   7  Pasien               pasien                   (sekaligus akun pasien)
--   8  Pendaftaran          kunjungan                sumber (Langsung, Janji
--                                                    Temu, Online) + status
--   9  Rekam medis          rekam_medis              jenis_catatan -- SEMUA
--                                                    catatan klinis, lengkap
--                                                    dengan sumbernya: cabang,
--                                                    layanan, unit/poli, dokter,
--                                                    penulis, jam masuk
--  10  Order pelayanan      order_pelayanan          jenis (Tindakan,
--                                                    Laboratorium, Radiologi)
--  11  Farmasi              resep, resep_item, obat, stok_batch
--  12  Rawat inap           rawat_inap, transfer_bed
--  13  Gudang               mutasi_stok              jenis (Masuk, Keluar,
--                                                    Dispensing, Retur,
--                                                    Penyesuaian)
--                           pengadaan                jenis (Permintaan Unit,
--                                                    Purchase Request)
--  14  Keuangan             tagihan, tagihan_detail
--                           pembayaran               jenis (Pembayaran Pasien,
--                                                    Klaim Penjamin)
--  15  Jejak audit          audit_log
--
--  Kolom id_rs menandai CABANG asal data (pegawai, unit, kunjungan,
--  rekam medis, pengadaan, audit).
-- =====================================================================

SET NAMES utf8mb4;
CREATE DATABASE IF NOT EXISTS db_simrs_ushi CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE db_simrs_ushi;

SET FOREIGN_KEY_CHECKS = 0;
-- tabel versi lama (bila database pernah diimport sebelumnya)
DROP TABLE IF EXISTS klaim, penerimaan_barang, purchase_request, permintaan_unit,
    catatan_keperawatan, ranap, order_radiologi, order_lab, retur_obat,
    tindakan_kunjungan, dokumen_klinis, addendum, igd_tindakan, triase_igd,
    pengkajian_awal, appointment, jadwal_dokter, pengguna, jenis_radiologi,
    jenis_lab, tarif, kamar, poliklinik, pengaturan;
-- tabel versi sekarang
DROP TABLE IF EXISTS audit_log, pembayaran, tagihan_detail, tagihan, pengadaan,
    mutasi_stok, transfer_bed, rawat_inap, resep_item, resep, order_pelayanan,
    rekam_medis, kunjungan, pasien, jadwal_pegawai, pegawai, hak_akses, modul,
    role, stok_batch, obat, icd10, penjamin, layanan, bed, unit_layanan,
    konfigurasi_rs;
SET FOREIGN_KEY_CHECKS = 1;


-- =====================================================================
-- 1. KONFIGURASI RS -- identitas rumah sakit pusat & cabang
--    (semua teks identitas di aplikasi diambil dari sini)
-- =====================================================================
CREATE TABLE konfigurasi_rs (
    id                  INT UNSIGNED  NOT NULL AUTO_INCREMENT PRIMARY KEY,
    kode                VARCHAR(10)   NOT NULL UNIQUE,            -- TBT, DPK, BKS
    jenis               ENUM('Pusat','Cabang') NOT NULL,
    id_pusat            INT UNSIGNED  NULL,                       -- cabang -> RS pusat
    nama_rs             VARCHAR(150)  NOT NULL,                   -- nama resmi
    singkatan           VARCHAR(30)   NOT NULL,                   -- nama singkat (logo, judul)
    nama_cabang         VARCHAR(60)   NOT NULL,                   -- Tebet, Depok, Bekasi
    slogan              VARCHAR(150)  NULL,
    alamat              VARCHAR(255)  NOT NULL,
    kota                VARCHAR(60)   NOT NULL,
    telepon             VARCHAR(20)   NOT NULL,                   -- pendaftaran
    telepon_igd         VARCHAR(20)   NOT NULL,
    email               VARCHAR(100)  NULL,
    kode_faskes         VARCHAR(20)   NOT NULL UNIQUE,            -- kode faskes (simulasi SATUSEHAT/BPJS)
    lokasi_igd          VARCHAR(100)  NOT NULL,                   -- mis. Gedung B lantai 1
    jam_besuk           VARCHAR(100)  NOT NULL,
    batas_persetujuan_asuransi DECIMAL(12,2) NOT NULL DEFAULT 1000000,  -- order >= nilai ini butuh surat jaminan asuransi
    aktif               TINYINT(1)    NOT NULL DEFAULT 1,
    CONSTRAINT chk_rs_batas CHECK (batas_persetujuan_asuransi >= 0),
    CONSTRAINT chk_rs_pusat CHECK ((jenis = 'Pusat' AND id_pusat IS NULL) OR (jenis = 'Cabang' AND id_pusat IS NOT NULL)),
    FOREIGN KEY (id_pusat) REFERENCES konfigurasi_rs(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- =====================================================================
-- 2. HAK AKSES (RBAC) -- Modul 1 Authentication & User Management
-- =====================================================================
CREATE TABLE role (
    kode        VARCHAR(20)  NOT NULL PRIMARY KEY,
    nama        VARCHAR(100) NOT NULL UNIQUE,
    keterangan  VARCHAR(255) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Modul SIMRS. Menu sidebar dibangun dari tabel ini.
CREATE TABLE modul (
    kode    VARCHAR(20)  NOT NULL PRIMARY KEY,
    nomor   TINYINT      NOT NULL,
    nama    VARCHAR(100) NOT NULL,
    grup    VARCHAR(30)  NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Matriks hak akses: role X boleh membuka modul Y (lihat) dan/atau mengubah.
CREATE TABLE hak_akses (
    role       VARCHAR(20) NOT NULL,
    modul      VARCHAR(20) NOT NULL,
    bisa_ubah  TINYINT(1)  NOT NULL DEFAULT 0,
    PRIMARY KEY (role, modul),
    FOREIGN KEY (role)  REFERENCES role(kode)  ON DELETE CASCADE ON UPDATE CASCADE,
    FOREIGN KEY (modul) REFERENCES modul(kode) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- =====================================================================
-- 3. KEPEGAWAIAN -- SATU tabel untuk semua tenaga, dibedakan jenis_tenaga.
--    Kolom yang tidak berlaku untuk jenis tertentu dibiarkan kosong (NULL),
--    mis. spesialisasi hanya untuk dokter.
--    STR = Surat Tanda Registrasi, SIP = Surat Izin Praktik
--    (perawat: SIPP, apoteker: SIPA, bidan: SIPB, analis: SIP-ATLM).
--    Akun login (username, password, role) melekat pada pegawai.
-- =====================================================================
CREATE TABLE unit_layanan (                                       -- dibuat dulu (dirujuk pegawai)
    id                INT UNSIGNED  NOT NULL AUTO_INCREMENT PRIMARY KEY,
    id_rs             INT UNSIGNED  NOT NULL,                     -- cabang pemilik unit
    kode              VARCHAR(15)   NOT NULL UNIQUE,              -- TBT-PD, DPK-IGD, TBT-R201
    nama              VARCHAR(100)  NOT NULL,
    jenis             ENUM('Poliklinik','IGD','Rawat Inap') NOT NULL,
    kode_antrian      CHAR(1)       NULL,                         -- Poliklinik/IGD: huruf antrean, mis. B-003
    kelas             ENUM('VIP','I','II','III','ICU','Isolasi') NULL,  -- Rawat Inap
    lokasi            VARCHAR(60)   NOT NULL,                     -- gedung & lantai
    tarif             DECIMAL(12,2) NOT NULL DEFAULT 0,           -- konsultasi (poli/IGD) atau per hari (rawat inap)
    aktif             TINYINT(1)    NOT NULL DEFAULT 1,
    CONSTRAINT uq_unit_nama   UNIQUE (id_rs, nama),
    CONSTRAINT uq_unit_antre  UNIQUE (id_rs, kode_antrian),
    CONSTRAINT chk_unit_tarif CHECK (tarif >= 0),
    CONSTRAINT chk_unit_antre CHECK (kode_antrian IS NULL OR kode_antrian REGEXP '^[A-Z]$'),
    CONSTRAINT chk_unit_kelas CHECK ((jenis = 'Rawat Inap' AND kelas IS NOT NULL) OR (jenis <> 'Rawat Inap' AND kelas IS NULL)),
    FOREIGN KEY (id_rs) REFERENCES konfigurasi_rs(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE pegawai (
    id                    INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    id_rs                 INT UNSIGNED NOT NULL,                  -- cabang tempat bekerja
    kode_pegawai          VARCHAR(10)  NOT NULL UNIQUE,           -- DR-001, PR-001, ...
    nik                   CHAR(16)     NOT NULL UNIQUE,
    nama_lengkap          VARCHAR(150) NOT NULL,
    jenis_tenaga          ENUM('Dokter','Perawat','Bidan','Apoteker','Analis Lab','Radiografer','Administrasi') NOT NULL,
    jabatan               VARCHAR(100) NOT NULL,                  -- mis. Dokter Spesialis, Kasir, Kepala Ruangan
    spesialisasi          VARCHAR(100) NULL,                      -- khusus dokter
    id_unit               INT UNSIGNED NULL,                      -- unit kerja utama
    no_str                VARCHAR(30)  NULL UNIQUE,               -- tenaga kesehatan
    berlaku_str           DATE         NULL,
    no_sip                VARCHAR(40)  NULL UNIQUE,               -- SIP / SIPP / SIPA / SIPB
    berlaku_sip           DATE         NULL,
    jenis_kelamin         ENUM('L','P') NOT NULL,
    tanggal_lahir         DATE         NULL,
    no_hp                 VARCHAR(15)  NOT NULL,
    email                 VARCHAR(100) NULL UNIQUE,
    alamat                VARCHAR(255) NULL,
    tanggal_masuk         DATE         NULL,
    status                ENUM('Aktif','Cuti','Nonaktif') NOT NULL DEFAULT 'Aktif',
    -- akun login SIMRS
    username              VARCHAR(50)  NULL UNIQUE,
    password              VARCHAR(255) NULL,                      -- hasil password_hash()
    role                  VARCHAR(20)  NULL,
    akun_aktif            TINYINT(1)   NOT NULL DEFAULT 1,
    wajib_ganti_password  TINYINT(1)   NOT NULL DEFAULT 0,
    gagal_login           TINYINT UNSIGNED NOT NULL DEFAULT 0,    -- 3x gagal -> dikunci 5 menit
    kunci_sampai          DATETIME     NULL,
    login_terakhir        DATETIME     NULL,
    created_at            TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_pegawai_nik  CHECK (nik REGEXP '^[0-9]{16}$'),
    CONSTRAINT chk_pegawai_hp   CHECK (no_hp REGEXP '^(08|[+]628|628)[0-9]{8,11}$'),
    CONSTRAINT chk_pegawai_user CHECK (username IS NULL OR username REGEXP '^[a-z0-9._]{3,50}$'),
    CONSTRAINT chk_pegawai_akun CHECK ((username IS NULL AND password IS NULL AND role IS NULL) OR (username IS NOT NULL AND password IS NOT NULL AND role IS NOT NULL)),
    CONSTRAINT chk_pegawai_str  CHECK (jenis_tenaga = 'Administrasi' OR no_str IS NOT NULL),
    CONSTRAINT chk_pegawai_spes CHECK (jenis_tenaga = 'Dokter' OR spesialisasi IS NULL),
    FOREIGN KEY (id_rs)   REFERENCES konfigurasi_rs(id),
    FOREIGN KEY (id_unit) REFERENCES unit_layanan(id) ON DELETE SET NULL,
    FOREIGN KEY (role)    REFERENCES role(kode)                   -- tanpa CASCADE: kolom dipakai di CHECK
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Jadwal kerja pegawai: Praktik (dokter di poli, dipakai janji temu) / Shift
CREATE TABLE jadwal_pegawai (
    id           INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    id_pegawai   INT UNSIGNED NOT NULL,
    id_unit      INT UNSIGNED NOT NULL,                           -- unit (poli) di cabang mana
    jenis        ENUM('Praktik','Shift') NOT NULL DEFAULT 'Praktik',
    hari         ENUM('Senin','Selasa','Rabu','Kamis','Jumat','Sabtu','Minggu') NOT NULL,
    jam_mulai    TIME         NOT NULL,
    jam_selesai  TIME         NOT NULL,
    durasi_slot  TINYINT UNSIGNED NOT NULL DEFAULT 15,            -- menit per pasien (janji temu)
    kuota        SMALLINT UNSIGNED NOT NULL DEFAULT 20,
    aktif        TINYINT(1)   NOT NULL DEFAULT 1,
    CONSTRAINT uq_jadwal UNIQUE (id_pegawai, id_unit, hari),
    CONSTRAINT chk_jadwal_jam   CHECK (jam_selesai > jam_mulai),
    CONSTRAINT chk_jadwal_kuota CHECK (kuota BETWEEN 1 AND 200),
    CONSTRAINT chk_jadwal_slot  CHECK (durasi_slot BETWEEN 5 AND 60),
    FOREIGN KEY (id_pegawai) REFERENCES pegawai(id) ON DELETE CASCADE,
    FOREIGN KEY (id_unit)    REFERENCES unit_layanan(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- =====================================================================
-- 4. UNIT & RUANGAN -- unit_layanan (di atas) + bed rawat inap
-- =====================================================================
CREATE TABLE bed (
    id        INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    id_unit   INT UNSIGNED NOT NULL,                              -- unit jenis Rawat Inap
    kode_bed  CHAR(1)      NOT NULL,
    status    ENUM('Tersedia','Terisi','Perbaikan') NOT NULL DEFAULT 'Tersedia',
    CONSTRAINT uq_bed UNIQUE (id_unit, kode_bed),
    CONSTRAINT chk_bed_kode CHECK (kode_bed REGEXP '^[A-Z]$'),
    FOREIGN KEY (id_unit) REFERENCES unit_layanan(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- =====================================================================
-- 5. LAYANAN & TARIF -- SATU katalog untuk semua layanan yang bisa diorder.
--    Kolom khusus kategori dibiarkan kosong untuk kategori lain:
--      Tindakan     : wajib_keterangan, invasif, petunjuk
--      Laboratorium : sub_kategori (Hematologi ...), spesimen, perlu_puasa, nilai_normal
--      Radiologi    : sub_kategori (X-Ray, USG, CT Scan, MRI), bagian_tubuh,
--                     bisa_kontras, biaya_kontras, pilih_sisi
--      Paket Lab    : isi_paket (kode layanan lab, dipisah koma)
-- =====================================================================
CREATE TABLE layanan (
    id                INT UNSIGNED  NOT NULL AUTO_INCREMENT PRIMARY KEY,
    kode              VARCHAR(20)   NOT NULL UNIQUE,
    nama              VARCHAR(150)  NOT NULL,
    kategori          ENUM('Administrasi','Tindakan','Laboratorium','Radiologi','Paket Lab') NOT NULL,
    sub_kategori      VARCHAR(30)   NULL,
    harga             DECIMAL(12,2) NOT NULL DEFAULT 0,
    persiapan         VARCHAR(255)  NULL,                         -- persiapan pasien
    wajib_keterangan  TINYINT(1)    NOT NULL DEFAULT 0,
    invasif           TINYINT(1)    NOT NULL DEFAULT 0,
    petunjuk          VARCHAR(120)  NULL,
    spesimen          VARCHAR(40)   NULL,
    perlu_puasa       TINYINT(1)    NOT NULL DEFAULT 0,
    nilai_normal      VARCHAR(255)  NULL,
    bagian_tubuh      VARCHAR(60)   NULL,
    bisa_kontras      TINYINT(1)    NOT NULL DEFAULT 0,
    biaya_kontras     DECIMAL(12,2) NOT NULL DEFAULT 0,
    pilih_sisi        TINYINT(1)    NOT NULL DEFAULT 0,
    isi_paket         VARCHAR(255)  NULL,
    aktif             TINYINT(1)    NOT NULL DEFAULT 1,
    CONSTRAINT uq_layanan_nama  UNIQUE (kategori, nama),
    CONSTRAINT uq_layanan_rad   UNIQUE (kategori, sub_kategori, bagian_tubuh),
    CONSTRAINT chk_layanan_harga CHECK (harga >= 0 AND biaya_kontras >= 0),
    CONSTRAINT chk_layanan_lab  CHECK (kategori <> 'Laboratorium' OR (sub_kategori IS NOT NULL AND spesimen IS NOT NULL AND nilai_normal IS NOT NULL)),
    CONSTRAINT chk_layanan_rad  CHECK (kategori <> 'Radiologi' OR (sub_kategori IN ('X-Ray','USG','CT Scan','MRI') AND bagian_tubuh IS NOT NULL)),
    CONSTRAINT chk_layanan_pkt  CHECK (kategori <> 'Paket Lab' OR isi_paket IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- =====================================================================
-- 6. REFERENSI
-- =====================================================================
CREATE TABLE penjamin (
    id     INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    kode   VARCHAR(20)  NOT NULL UNIQUE,
    nama   VARCHAR(100) NOT NULL UNIQUE,
    tipe   ENUM('Umum','BPJS','Asuransi') NOT NULL,
    aktif  TINYINT(1)   NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE icd10 (
    kode   VARCHAR(10)  NOT NULL PRIMARY KEY,
    nama   VARCHAR(255) NOT NULL,
    aktif  TINYINT(1)   NOT NULL DEFAULT 1,
    CONSTRAINT chk_icd_kode CHECK (kode REGEXP '^[A-Z][0-9]{2}([.][0-9A-Z]{1,4})?$')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- =====================================================================
-- 7. PASIEN -- data pasien terpusat untuk semua cabang (satu No. RM)
--    + akun Akun Pasien (opsional)
-- =====================================================================
CREATE TABLE pasien (
    id                    INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    nomor_rm              VARCHAR(20)  NOT NULL UNIQUE,           -- RM-2026-000001
    nama_lengkap          VARCHAR(150) NOT NULL,
    nik                   CHAR(16)     NOT NULL UNIQUE,
    tanggal_lahir         DATE         NOT NULL,
    jenis_kelamin         ENUM('L','P') NOT NULL,
    golongan_darah        ENUM('A','B','AB','O','?') NOT NULL DEFAULT '?',
    alamat                VARCHAR(255) NOT NULL,
    no_hp                 VARCHAR(15)  NOT NULL,
    no_bpjs               CHAR(13)     NULL UNIQUE,
    alergi                VARCHAR(255) NULL,
    id_rs_daftar          INT UNSIGNED NULL,                      -- cabang tempat pertama terdaftar
    dibuat_oleh           INT UNSIGNED NULL,                      -- pegawai
    -- akun Akun Pasien (daftar sendiri lewat daftar.php)
    username              VARCHAR(50)  NULL UNIQUE,
    password              VARCHAR(255) NULL,
    akun_aktif            TINYINT(1)   NOT NULL DEFAULT 1,
    gagal_login           TINYINT UNSIGNED NOT NULL DEFAULT 0,
    kunci_sampai          DATETIME     NULL,
    login_terakhir        DATETIME     NULL,
    created_at            TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_pasien_rm   CHECK (nomor_rm REGEXP '^RM-[0-9]{4}-[0-9]{6}$'),
    CONSTRAINT chk_pasien_nik  CHECK (nik REGEXP '^[0-9]{16}$'),
    CONSTRAINT chk_pasien_hp   CHECK (no_hp REGEXP '^(08|[+]628|628)[0-9]{8,11}$'),
    CONSTRAINT chk_pasien_bpjs CHECK (no_bpjs IS NULL OR no_bpjs REGEXP '^[0-9]{13}$'),
    CONSTRAINT chk_pasien_user CHECK (username IS NULL OR username REGEXP '^[a-z0-9._]{3,50}$'),
    CONSTRAINT chk_pasien_akun CHECK ((username IS NULL AND password IS NULL) OR (username IS NOT NULL AND password IS NOT NULL)),
    FOREIGN KEY (id_rs_daftar) REFERENCES konfigurasi_rs(id) ON DELETE SET NULL,
    FOREIGN KEY (dibuat_oleh)  REFERENCES pegawai(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- =====================================================================
-- 8. PENDAFTARAN -- kunjungan (sekaligus janji temu)
--    sumber : Langsung (datang ke loket) | Janji Temu (dibuat petugas)
--             | Online (dibuat pasien lewat Akun Pasien)
--    status : Menunggu Konfirmasi -> Terkonfirmasi   (janji temu, belum datang)
--             -> Menunggu (sudah datang, dapat antrean) -> Dipanggil
--             -> Selesai | Batal
--    jenis  : rawat_jalan | igd | rawat_inap
-- =====================================================================
CREATE TABLE kunjungan (
    id               INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    id_rs            INT UNSIGNED NOT NULL,                       -- cabang tempat berobat
    kode_booking     VARCHAR(20)  NULL UNIQUE,                    -- APT-2026-000001 (janji temu)
    id_pasien        INT UNSIGNED NOT NULL,
    tanggal          DATE         NOT NULL,
    jam_janji        TIME         NULL,                           -- jam yang dipilih (janji temu / pendaftaran)
    no_antrian       VARCHAR(10)  NULL,                           -- diisi saat pasien datang
    id_unit          INT UNSIGNED NOT NULL,                       -- poli / IGD / ruang rawat
    id_dokter        INT UNSIGNED NOT NULL,                       -- pegawai.id (DPJP)
    id_jadwal        INT UNSIGNED NULL,
    id_penjamin      INT UNSIGNED NOT NULL,
    no_kartu         VARCHAR(30)  NULL,                           -- no. BPJS / polis asuransi
    keluhan_awal     VARCHAR(255) NULL,
    jenis            ENUM('rawat_jalan','igd','rawat_inap') NOT NULL DEFAULT 'rawat_jalan',
    sumber           ENUM('Langsung','Janji Temu','Online') NOT NULL DEFAULT 'Langsung',
    status           ENUM('Menunggu Konfirmasi','Terkonfirmasi','Menunggu','Dipanggil','Selesai','Batal') NOT NULL DEFAULT 'Menunggu',
    waktu_masuk      DATETIME     NULL,                           -- jam pasien tiba / didaftarkan di loket
    catatan          VARCHAR(255) NULL,
    dibuat_oleh      INT UNSIGNED NULL,                           -- pegawai (NULL = dibuat pasien online)
    created_at       TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_antrian UNIQUE (tanggal, id_unit, no_antrian),
    CONSTRAINT chk_kunj_antre CHECK (status IN ('Menunggu Konfirmasi','Terkonfirmasi','Batal') OR no_antrian IS NOT NULL),
    FOREIGN KEY (id_rs)       REFERENCES konfigurasi_rs(id),
    FOREIGN KEY (id_pasien)   REFERENCES pasien(id),             -- RESTRICT: rekam medis dilindungi
    FOREIGN KEY (id_unit)     REFERENCES unit_layanan(id),
    FOREIGN KEY (id_dokter)   REFERENCES pegawai(id),
    FOREIGN KEY (id_jadwal)   REFERENCES jadwal_pegawai(id) ON DELETE SET NULL,
    FOREIGN KEY (id_penjamin) REFERENCES penjamin(id),
    FOREIGN KEY (dibuat_oleh) REFERENCES pegawai(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- =====================================================================
-- 9. REKAM MEDIS -- SEMUA catatan klinis dalam SATU tabel.
--    Setiap baris menyimpan SUMBERNYA secara langsung:
--      id_rs (cabang), jenis_layanan, id_unit (poli/IGD/ruang), id_dokter (DPJP),
--      waktu_masuk (jam pasien masuk), ditulis_oleh + waktu_catat (siapa & kapan).
--    jenis_catatan menentukan kolom yang terisi:
--      Pengkajian Awal      : TTV + keluhan_utama + riwayat            (perawat RJ)
--      Triase IGD           : TTV + gcs + triase_kategori + keluhan    (perawat IGD)
--      Penanganan IGD       : tahap_igd + catatan + tindakan + disposisi (dokter IGD)
--      SOAP Dokter          : subjektif..plan + kode_icd10 + tindak_lanjut, Draft->Final
--      Catatan Keperawatan  : TTV + catatan                             (rawat inap)
--      Pemberian Obat       : id_resep_item + catatan
--      Lapor DPJP           : catatan + urgensi + dibaca_dpjp
--      Addendum             : catatan + id_induk (SOAP yang dikoreksi)
--      Resume Pulang        : assessment (diagnosis akhir) + kode_icd10 + plan (terapi) + catatan (instruksi)
--      Surat Kontrol / Surat Rujukan : catatan + tanggal_kontrol / tujuan
-- =====================================================================
CREATE TABLE rekam_medis (
    id                  INT UNSIGNED  NOT NULL AUTO_INCREMENT PRIMARY KEY,
    -- sumber
    id_rs               INT UNSIGNED  NOT NULL,
    id_kunjungan        INT UNSIGNED  NOT NULL,
    id_pasien           INT UNSIGNED  NOT NULL,
    jenis_layanan       ENUM('Rawat Jalan','IGD','Rawat Inap') NOT NULL,
    id_unit             INT UNSIGNED  NOT NULL,
    id_dokter           INT UNSIGNED  NOT NULL,                   -- DPJP kunjungan
    waktu_masuk         DATETIME      NOT NULL,                   -- jam pasien masuk
    jenis_catatan       ENUM('Pengkajian Awal','Triase IGD','Penanganan IGD','SOAP Dokter','Catatan Keperawatan','Pemberian Obat','Lapor DPJP','Addendum','Resume Pulang','Surat Kontrol','Surat Rujukan') NOT NULL,
    ditulis_oleh        INT UNSIGNED  NOT NULL,                   -- pegawai penulis
    waktu_catat         TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    kunci_unik          VARCHAR(40)   NULL UNIQUE,                -- cegah ganda: 1 SOAP / 1 pengkajian / 1 triase / 1 resume per kunjungan
    -- tanda vital
    tekanan_darah       VARCHAR(10)   NULL,
    nadi                SMALLINT      NULL,
    respirasi           SMALLINT      NULL,
    suhu                DECIMAL(4,1)  NULL,
    spo2                TINYINT       NULL,
    berat_badan         DECIMAL(5,1)  NULL,
    tinggi_badan        DECIMAL(5,1)  NULL,
    gcs                 TINYINT       NULL,
    skala_nyeri         TINYINT       NULL,
    -- pengkajian / triase / IGD
    keluhan_utama       TEXT          NULL,
    riwayat             TEXT          NULL,
    triase_kategori     ENUM('Merah','Kuning','Hijau','Hitam') NULL,
    tahap_igd           ENUM('Pemeriksaan Awal','Tindakan','Observasi','Disposisi') NULL,
    tindakan            TEXT          NULL,
    disposisi           ENUM('Pulang','Rawat Inap','Rujuk') NULL,
    -- SOAP dokter
    subjektif           TEXT          NULL,
    objektif            TEXT          NULL,
    assessment          TEXT          NULL,
    kode_icd10          VARCHAR(10)   NULL,
    plan                TEXT          NULL,
    tindak_lanjut       ENUM('Pulang','Kontrol','Rawat Inap','Rujuk') NULL,
    status              ENUM('Draft','Final') NOT NULL DEFAULT 'Final',
    finalisasi_at       DATETIME      NULL,
    status_verifikasi   ENUM('Belum','Lengkap','Tidak Lengkap') NULL,   -- verifikasi unit rekam medis (SOAP)
    catatan_verifikasi  VARCHAR(255)  NULL,
    diverifikasi_oleh   INT UNSIGNED  NULL,
    satusehat_ref       VARCHAR(40)   NULL,
    -- catatan umum / keperawatan / addendum / dokumen
    catatan             TEXT          NULL,
    id_induk            INT UNSIGNED  NULL,                       -- addendum -> SOAP
    id_resep_item       INT UNSIGNED  NULL,                       -- pemberian obat
    urgensi             ENUM('Rutin','Segera') NULL,              -- lapor DPJP
    dibaca_dpjp         TINYINT(1)    NOT NULL DEFAULT 0,
    tanggal_kontrol     DATE          NULL,
    tujuan              VARCHAR(150)  NULL,                       -- RS / dokter rujukan
    CONSTRAINT chk_rm_td    CHECK (tekanan_darah IS NULL OR tekanan_darah REGEXP '^[0-9]{2,3}/[0-9]{2,3}$'),
    CONSTRAINT chk_rm_nadi  CHECK (nadi IS NULL OR nadi BETWEEN 0 AND 250),
    CONSTRAINT chk_rm_rr    CHECK (respirasi IS NULL OR respirasi BETWEEN 0 AND 80),
    CONSTRAINT chk_rm_suhu  CHECK (suhu IS NULL OR suhu BETWEEN 25 AND 45),
    CONSTRAINT chk_rm_spo2  CHECK (spo2 IS NULL OR spo2 BETWEEN 0 AND 100),
    CONSTRAINT chk_rm_bb    CHECK (berat_badan IS NULL OR berat_badan BETWEEN 0.5 AND 400),
    CONSTRAINT chk_rm_tb    CHECK (tinggi_badan IS NULL OR tinggi_badan BETWEEN 30 AND 250),
    CONSTRAINT chk_rm_gcs   CHECK (gcs IS NULL OR gcs BETWEEN 3 AND 15),
    CONSTRAINT chk_rm_nyeri CHECK (skala_nyeri IS NULL OR skala_nyeri BETWEEN 0 AND 10),
    CONSTRAINT chk_rm_soap  CHECK (jenis_catatan <> 'SOAP Dokter' OR (subjektif IS NOT NULL AND objektif IS NOT NULL AND assessment IS NOT NULL AND kode_icd10 IS NOT NULL AND plan IS NOT NULL)),
    CONSTRAINT chk_rm_triase CHECK (jenis_catatan <> 'Triase IGD' OR (triase_kategori IS NOT NULL AND gcs IS NOT NULL)),
    CONSTRAINT chk_rm_add   CHECK (jenis_catatan <> 'Addendum' OR id_induk IS NOT NULL),
    FOREIGN KEY (id_rs)             REFERENCES konfigurasi_rs(id),
    FOREIGN KEY (id_kunjungan)      REFERENCES kunjungan(id) ON DELETE CASCADE,
    FOREIGN KEY (id_pasien)         REFERENCES pasien(id),
    FOREIGN KEY (id_unit)           REFERENCES unit_layanan(id),
    FOREIGN KEY (id_dokter)         REFERENCES pegawai(id),
    FOREIGN KEY (ditulis_oleh)      REFERENCES pegawai(id),
    FOREIGN KEY (kode_icd10)        REFERENCES icd10(kode),        -- tanpa CASCADE: kolom dipakai di CHECK (MySQL 8)
    FOREIGN KEY (diverifikasi_oleh) REFERENCES pegawai(id),
    FOREIGN KEY (id_induk)          REFERENCES rekam_medis(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- =====================================================================
-- 10. ORDER PELAYANAN -- SATU tabel untuk order tindakan, lab, dan radiologi
--     (Modul 4 CPOE, 8 Laboratorium, 9 Radiologi)
--   Tindakan     : Order Baru -> Dikerjakan | Batal
--   Laboratorium : Order Baru -> Spesimen Diterima -> Diproses
--                  -> Menunggu Validasi -> Diterbitkan | Ditolak
--   Radiologi    : Order Baru -> Terverifikasi -> Terjadwal -> Pemeriksaan Selesai
--                  -> Gambar Terunggah -> Menunggu Ekspertise -> Diterbitkan | Ditolak
--   Petugas: id_petugas  = perawat pelaksana / ATLM / admin radiologi
--            id_petugas2 = radiografer
--            id_validator = dokter Sp.PK / Sp.Rad yang menerbitkan hasil
-- =====================================================================
CREATE TABLE order_pelayanan (
    id                   INT UNSIGNED  NOT NULL AUTO_INCREMENT PRIMARY KEY,
    id_kunjungan         INT UNSIGNED  NOT NULL,
    jenis                ENUM('Tindakan','Laboratorium','Radiologi') NOT NULL,
    id_layanan           INT UNSIGNED  NOT NULL,
    uraian               VARCHAR(200)  NOT NULL,                  -- label lengkap, mis. "CT Scan Kepala · Dengan kontras"
    id_dokter            INT UNSIGNED  NOT NULL,                  -- dokter pemesan
    jumlah               SMALLINT      NOT NULL DEFAULT 1,
    biaya                DECIMAL(12,2) NOT NULL,                  -- per satuan, disalin dari layanan saat order
    urgensi              ENUM('Rutin','CITO') NOT NULL DEFAULT 'Rutin',
    indikasi             VARCHAR(255)  NULL,
    status               ENUM('Order Baru','Spesimen Diterima','Diproses','Menunggu Validasi','Terverifikasi','Terjadwal','Pemeriksaan Selesai','Gambar Terunggah','Menunggu Ekspertise','Diterbitkan','Dikerjakan','Ditolak','Batal') NOT NULL DEFAULT 'Order Baru',
    kunci_unik           VARCHAR(60)   NULL UNIQUE,               -- lab/radiologi tidak boleh diorder dua kali per kunjungan
    -- tindakan
    pelaksana            ENUM('Dokter','Perawat') NULL,
    keterangan           VARCHAR(255)  NULL,                      -- lokasi / detail
    persetujuan          TINYINT(1)    NOT NULL DEFAULT 0,        -- informed consent
    -- laboratorium
    status_puasa         ENUM('-','Puasa','Tidak puasa') NOT NULL DEFAULT '-',
    hasil                TEXT          NULL,
    -- radiologi
    kontras              TINYINT(1)    NOT NULL DEFAULT 0,
    sisi                 ENUM('-','Kanan','Kiri','Bilateral') NOT NULL DEFAULT '-',
    status_hamil         ENUM('-','Tidak hamil','Hamil','Tidak tahu') NOT NULL DEFAULT '-',
    alasan_klinis        VARCHAR(255)  NULL,
    jadwal               DATETIME      NULL,
    file_gambar          VARCHAR(255)  NULL,
    temuan               TEXT          NULL,
    kesimpulan           TEXT          NULL,
    -- persetujuan asuransi (pre-otorisasi) untuk lab/radiologi mahal
    jaminan              ENUM('-','Menunggu Persetujuan','Disetujui','Bayar Sendiri','Ditolak') NOT NULL DEFAULT '-',
    catatan_jaminan      VARCHAR(255)  NULL,
    id_verif_jaminan     INT UNSIGNED  NULL,
    -- pelaksanaan
    catatan              VARCHAR(255)  NULL,                      -- catatan pelaksanaan / validasi / alasan tolak
    id_petugas           INT UNSIGNED  NULL,
    id_petugas2          INT UNSIGNED  NULL,
    id_validator         INT UNSIGNED  NULL,
    waktu_dikerjakan     DATETIME      NULL,
    waktu_terbit         DATETIME      NULL,
    created_at           TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_op_jumlah CHECK (jumlah BETWEEN 1 AND 50),
    CONSTRAINT chk_op_biaya  CHECK (biaya >= 0),
    CONSTRAINT chk_op_status CHECK (
        (jenis = 'Tindakan' AND status IN ('Order Baru','Dikerjakan','Batal')) OR
        (jenis = 'Laboratorium' AND status IN ('Order Baru','Spesimen Diterima','Diproses','Menunggu Validasi','Diterbitkan','Ditolak')) OR
        (jenis = 'Radiologi' AND status IN ('Order Baru','Terverifikasi','Terjadwal','Pemeriksaan Selesai','Gambar Terunggah','Menunggu Ekspertise','Diterbitkan','Ditolak'))),
    FOREIGN KEY (id_kunjungan)     REFERENCES kunjungan(id) ON DELETE CASCADE,
    FOREIGN KEY (id_layanan)       REFERENCES layanan(id),
    FOREIGN KEY (id_dokter)        REFERENCES pegawai(id),
    FOREIGN KEY (id_verif_jaminan) REFERENCES pegawai(id),
    FOREIGN KEY (id_petugas)       REFERENCES pegawai(id),
    FOREIGN KEY (id_petugas2)      REFERENCES pegawai(id),
    FOREIGN KEY (id_validator)     REFERENCES pegawai(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- =====================================================================
-- 11. FARMASI -- obat (stok total tidak boleh minus) + batch + e-resep
--   Resep: Order Baru -> Terverifikasi -> Dispensing (stok dipotong)
--          -> Siap Diserahkan -> Selesai | Batal
-- =====================================================================
CREATE TABLE obat (
    id            INT UNSIGNED  NOT NULL AUTO_INCREMENT PRIMARY KEY,
    kode          VARCHAR(20)   NOT NULL UNIQUE,
    nama_obat     VARCHAR(150)  NOT NULL UNIQUE,
    kategori      ENUM('Obat','Alkes/BHP') NOT NULL DEFAULT 'Obat',
    satuan        VARCHAR(30)   NOT NULL,
    stok          INT           NOT NULL DEFAULT 0,
    stok_minimum  INT           NOT NULL DEFAULT 10,
    harga_satuan  DECIMAL(12,2) NOT NULL,
    high_alert    TINYINT(1)    NOT NULL DEFAULT 0,
    lasa          TINYINT(1)    NOT NULL DEFAULT 0,               -- Look Alike Sound Alike
    aktif         TINYINT(1)    NOT NULL DEFAULT 1,
    CONSTRAINT chk_obat_stok  CHECK (stok >= 0),
    CONSTRAINT chk_obat_min   CHECK (stok_minimum >= 0),
    CONSTRAINT chk_obat_harga CHECK (harga_satuan >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Batch & tanggal kedaluwarsa (obat.stok = jumlah qty_sisa semua batch)
CREATE TABLE stok_batch (
    id               INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    id_obat          INT UNSIGNED NOT NULL,
    no_batch         VARCHAR(30)  NOT NULL,
    tgl_kedaluwarsa  DATE         NOT NULL,
    qty_sisa         INT          NOT NULL DEFAULT 0,
    lokasi           VARCHAR(60)  NOT NULL DEFAULT 'Gudang Farmasi',
    created_at       TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_batch UNIQUE (id_obat, no_batch),
    CONSTRAINT chk_batch_qty CHECK (qty_sisa >= 0),
    FOREIGN KEY (id_obat) REFERENCES obat(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE resep (
    id               INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    id_kunjungan     INT UNSIGNED NOT NULL,
    id_dokter        INT UNSIGNED NOT NULL,                       -- pegawai
    tanggal          DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    status           ENUM('Order Baru','Terverifikasi','Dispensing','Siap Diserahkan','Selesai','Batal') NOT NULL DEFAULT 'Order Baru',
    catatan_dokter   TEXT         NULL,
    catatan_farmasi  TEXT         NULL,
    diproses_oleh    INT UNSIGNED NULL,                           -- pegawai apoteker
    waktu_selesai    DATETIME     NULL,
    FOREIGN KEY (id_kunjungan)  REFERENCES kunjungan(id) ON DELETE CASCADE,
    FOREIGN KEY (id_dokter)     REFERENCES pegawai(id),
    FOREIGN KEY (diproses_oleh) REFERENCES pegawai(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE resep_item (
    id             INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    id_resep       INT UNSIGNED NOT NULL,
    id_obat        INT UNSIGNED NOT NULL,
    jumlah         INT          NOT NULL,
    dosis          VARCHAR(50)  NOT NULL,
    frekuensi      VARCHAR(50)  NOT NULL,
    aturan_pakai   VARCHAR(100) NOT NULL,
    alasan_alergi  TEXT         NULL,                             -- wajib bila obat cocok dengan alergi pasien
    jumlah_retur   INT          NOT NULL DEFAULT 0,               -- rincian retur ada di mutasi_stok (jenis Retur)
    CONSTRAINT chk_ri_jumlah CHECK (jumlah BETWEEN 1 AND 500),
    CONSTRAINT chk_ri_retur  CHECK (jumlah_retur BETWEEN 0 AND jumlah),
    CONSTRAINT uq_resep_obat UNIQUE (id_resep, id_obat),
    FOREIGN KEY (id_resep) REFERENCES resep(id) ON DELETE CASCADE,
    FOREIGN KEY (id_obat)  REFERENCES obat(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

ALTER TABLE rekam_medis ADD CONSTRAINT fk_rm_resep_item FOREIGN KEY (id_resep_item) REFERENCES resep_item(id) ON DELETE SET NULL;


-- =====================================================================
-- 12. RAWAT INAP -- Modul 6 (resume pulang ada di rekam_medis)
-- =====================================================================
CREATE TABLE rawat_inap (
    id                INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    id_kunjungan      INT UNSIGNED NOT NULL UNIQUE,
    id_bed            INT UNSIGNED NOT NULL,
    id_dokter         INT UNSIGNED NOT NULL,                      -- pegawai DPJP
    alasan_masuk      TEXT         NOT NULL,
    tanggal_masuk     DATETIME     NOT NULL,
    tanggal_keluar    DATETIME     NULL,
    status            ENUM('Aktif','Keluar') NOT NULL DEFAULT 'Aktif',
    ditempatkan_oleh  INT UNSIGNED NULL,                          -- perawat bangsal
    CONSTRAINT chk_ranap_tgl CHECK (tanggal_keluar IS NULL OR tanggal_keluar >= tanggal_masuk),
    FOREIGN KEY (id_kunjungan)     REFERENCES kunjungan(id) ON DELETE CASCADE,
    FOREIGN KEY (id_bed)           REFERENCES bed(id),
    FOREIGN KEY (id_dokter)        REFERENCES pegawai(id),
    FOREIGN KEY (ditempatkan_oleh) REFERENCES pegawai(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE transfer_bed (
    id             INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    id_rawat_inap  INT UNSIGNED NOT NULL,
    dari_bed       INT UNSIGNED NOT NULL,
    ke_bed         INT UNSIGNED NOT NULL,
    alasan         VARCHAR(255) NOT NULL,
    oleh           INT UNSIGNED NOT NULL,
    created_at     TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_transfer_beda CHECK (dari_bed <> ke_bed),
    FOREIGN KEY (id_rawat_inap) REFERENCES rawat_inap(id) ON DELETE CASCADE,
    FOREIGN KEY (dari_bed) REFERENCES bed(id),
    FOREIGN KEY (ke_bed)   REFERENCES bed(id),
    FOREIGN KEY (oleh)     REFERENCES pegawai(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- =====================================================================
-- 13. GUDANG -- Modul 14 Inventory & Warehouse
-- =====================================================================
-- Semua pergerakan stok: Masuk (penerimaan), Keluar (permintaan unit),
-- Dispensing (resep), Retur (obat dikembalikan pasien), Penyesuaian (opname)
CREATE TABLE mutasi_stok (
    id             INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    id_obat        INT UNSIGNED NOT NULL,
    id_batch       INT UNSIGNED NULL,
    jenis          ENUM('Masuk','Keluar','Dispensing','Retur','Penyesuaian') NOT NULL,
    jumlah         INT          NOT NULL,                         -- positif = masuk, negatif = keluar
    id_resep_item  INT UNSIGNED NULL,                             -- Dispensing / Retur
    id_pengadaan   INT UNSIGNED NULL,                             -- Masuk / Keluar
    keterangan     VARCHAR(255) NULL,
    oleh           INT UNSIGNED NULL,
    created_at     TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_mutasi_nol CHECK (jumlah <> 0),
    FOREIGN KEY (id_obat)       REFERENCES obat(id) ON DELETE CASCADE,
    FOREIGN KEY (id_batch)      REFERENCES stok_batch(id) ON DELETE SET NULL,
    FOREIGN KEY (id_resep_item) REFERENCES resep_item(id) ON DELETE SET NULL,
    FOREIGN KEY (oleh)          REFERENCES pegawai(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Pengadaan barang:
--   Permintaan Unit  : Diajukan -> Dikeluarkan | Ditolak   (unit meminta ke gudang)
--   Purchase Request : Diajukan -> Disetujui -> Diterima | Ditolak (gudang -> manajemen -> supplier)
CREATE TABLE pengadaan (
    id               INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    id_rs            INT UNSIGNED NOT NULL,
    kode             VARCHAR(20)  NOT NULL UNIQUE,                -- REQ-2026-000001 / PR-2026-000001
    jenis            ENUM('Permintaan Unit','Purchase Request') NOT NULL,
    id_obat          INT UNSIGNED NOT NULL,
    jumlah           INT          NOT NULL,
    unit_peminta     VARCHAR(60)  NULL,                           -- Permintaan Unit
    alasan           VARCHAR(255) NULL,
    status           ENUM('Diajukan','Dikeluarkan','Disetujui','Diterima','Ditolak') NOT NULL DEFAULT 'Diajukan',
    diajukan_oleh    INT UNSIGNED NOT NULL,
    diproses_oleh    INT UNSIGNED NULL,                           -- gudang (keluarkan) / manajemen (setujui)
    catatan          VARCHAR(255) NULL,
    -- penerimaan barang (Purchase Request)
    no_po            VARCHAR(30)  NULL,
    supplier         VARCHAR(100) NULL,
    id_batch         INT UNSIGNED NULL,
    jumlah_diterima  INT          NULL,
    kondisi          ENUM('Baik','Rusak Sebagian') NULL,
    diterima_oleh    INT UNSIGNED NULL,
    waktu_terima     DATETIME     NULL,
    created_at       TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_pengadaan_jumlah CHECK (jumlah BETWEEN 1 AND 100000),
    CONSTRAINT chk_pengadaan_status CHECK (
        (jenis = 'Permintaan Unit' AND status IN ('Diajukan','Dikeluarkan','Ditolak')) OR
        (jenis = 'Purchase Request' AND status IN ('Diajukan','Disetujui','Diterima','Ditolak'))),
    FOREIGN KEY (id_rs)         REFERENCES konfigurasi_rs(id),
    FOREIGN KEY (id_obat)       REFERENCES obat(id),
    FOREIGN KEY (diajukan_oleh) REFERENCES pegawai(id),
    FOREIGN KEY (diproses_oleh) REFERENCES pegawai(id),
    FOREIGN KEY (id_batch)      REFERENCES stok_batch(id) ON DELETE SET NULL,
    FOREIGN KEY (diterima_oleh) REFERENCES pegawai(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

ALTER TABLE mutasi_stok ADD CONSTRAINT fk_mutasi_pengadaan FOREIGN KEY (id_pengadaan) REFERENCES pengadaan(id) ON DELETE SET NULL;


-- =====================================================================
-- 14. KEUANGAN -- Modul 11 Billing & Insurance
--   Tagihan: Menunggu Verifikasi -> Terverifikasi -> Dihitung -> Dibayar -> Final
--   Pembayaran: jenis Pembayaran Pasien (kasir) | Klaim Penjamin (verifikator)
-- =====================================================================
CREATE TABLE tagihan (
    id                  INT UNSIGNED  NOT NULL AUTO_INCREMENT PRIMARY KEY,
    no_tagihan          VARCHAR(20)   NOT NULL UNIQUE,            -- INV-2026-000001
    id_kunjungan        INT UNSIGNED  NOT NULL UNIQUE,            -- 1 kunjungan = 1 tagihan
    status              ENUM('Menunggu Verifikasi','Terverifikasi','Dihitung','Dibayar','Final') NOT NULL DEFAULT 'Menunggu Verifikasi',
    total               DECIMAL(12,2) NOT NULL DEFAULT 0,
    porsi_penjamin      DECIMAL(12,2) NOT NULL DEFAULT 0,
    porsi_pasien        DECIMAL(12,2) NOT NULL DEFAULT 0,
    plafon_penjamin     DECIMAL(12,2) NULL,                       -- batas tanggungan asuransi
    catatan_verifikasi  VARCHAR(255)  NULL,
    diverifikasi_oleh   INT UNSIGNED  NULL,
    dihitung_oleh       INT UNSIGNED  NULL,
    dikunci_oleh        INT UNSIGNED  NULL,
    dikunci_at          DATETIME      NULL,
    created_at          TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_tagihan_porsi CHECK (porsi_penjamin >= 0 AND porsi_pasien >= 0),
    FOREIGN KEY (id_kunjungan)      REFERENCES kunjungan(id),
    FOREIGN KEY (diverifikasi_oleh) REFERENCES pegawai(id),
    FOREIGN KEY (dihitung_oleh)     REFERENCES pegawai(id),
    FOREIGN KEY (dikunci_oleh)      REFERENCES pegawai(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE tagihan_detail (
    id          INT UNSIGNED  NOT NULL AUTO_INCREMENT PRIMARY KEY,
    id_tagihan  INT UNSIGNED  NOT NULL,
    komponen    ENUM('Administrasi','Konsultasi','Tindakan','Obat','Laboratorium','Radiologi','Kamar') NOT NULL,
    uraian      VARCHAR(200)  NOT NULL,
    qty         INT           NOT NULL,
    harga       DECIMAL(12,2) NOT NULL,
    subtotal    DECIMAL(12,2) NOT NULL,
    CONSTRAINT chk_td_qty CHECK (qty >= 1),
    FOREIGN KEY (id_tagihan) REFERENCES tagihan(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE pembayaran (
    id              INT UNSIGNED  NOT NULL AUTO_INCREMENT PRIMARY KEY,
    jenis           ENUM('Pembayaran Pasien','Klaim Penjamin') NOT NULL,
    no_transaksi    VARCHAR(25)   NOT NULL UNIQUE,                -- KW-2026-000001 / KLM-2026-000001
    id_tagihan      INT UNSIGNED  NOT NULL,
    id_penjamin     INT UNSIGNED  NULL,                           -- klaim penjamin
    metode          ENUM('tunai','debit','qris','transfer','bpjs','asuransi') NOT NULL,
    jumlah_tagihan  DECIMAL(12,2) NOT NULL,                       -- porsi pasien / jumlah klaim
    jumlah_dibayar  DECIMAL(12,2) NOT NULL DEFAULT 0,
    kembalian       DECIMAL(12,2) NOT NULL DEFAULT 0,
    status          ENUM('Lunas','Diajukan','Disetujui','Perlu Perbaikan','Ditolak') NOT NULL DEFAULT 'Lunas',
    catatan         VARCHAR(255)  NULL,
    dibuat_oleh     INT UNSIGNED  NOT NULL,
    created_at      TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_bayar_jenis UNIQUE (id_tagihan, jenis),         -- tidak bisa dibayar/diklaim dua kali
    CONSTRAINT chk_bayar_cukup CHECK (jenis <> 'Pembayaran Pasien' OR jumlah_dibayar >= jumlah_tagihan),
    CONSTRAINT chk_bayar_klaim CHECK (jenis <> 'Klaim Penjamin' OR id_penjamin IS NOT NULL),
    FOREIGN KEY (id_tagihan)  REFERENCES tagihan(id) ON DELETE CASCADE,
    FOREIGN KEY (id_penjamin) REFERENCES penjamin(id),
    FOREIGN KEY (dibuat_oleh) REFERENCES pegawai(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- =====================================================================
-- 15. JEJAK AUDIT -- siapa melakukan apa, di cabang mana
-- =====================================================================
CREATE TABLE audit_log (
    id           INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    id_rs        INT UNSIGNED NULL,
    id_pegawai   INT UNSIGNED NULL,                               -- NULL = pasien / tamu
    username     VARCHAR(50)  NOT NULL,
    modul        VARCHAR(60)  NOT NULL,
    aksi         VARCHAR(60)  NOT NULL,
    detail       TEXT         NULL,
    ip           VARCHAR(45)  NULL,
    created_at   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (id_rs)      REFERENCES konfigurasi_rs(id) ON DELETE SET NULL,
    FOREIGN KEY (id_pegawai) REFERENCES pegawai(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX idx_pasien_nama      ON pasien (nama_lengkap);
CREATE INDEX idx_pegawai_nama     ON pegawai (nama_lengkap);
CREATE INDEX idx_kunjungan_tgl    ON kunjungan (id_rs, tanggal, status);
CREATE INDEX idx_kunjungan_dokter ON kunjungan (id_dokter, tanggal);
CREATE INDEX idx_rm_kunjungan     ON rekam_medis (id_kunjungan, jenis_catatan);
CREATE INDEX idx_rm_pasien        ON rekam_medis (id_pasien, waktu_catat);
CREATE INDEX idx_order_status     ON order_pelayanan (jenis, status, urgensi);
CREATE INDEX idx_resep_status     ON resep (status);
CREATE INDEX idx_tagihan_status   ON tagihan (status);
CREATE INDEX idx_bayar_tgl        ON pembayaran (created_at);
CREATE INDEX idx_audit_tgl        ON audit_log (created_at);
